"""
apply_nova_fixes.py -- run this once from your project root (the folder
that directly contains backend/, dashboard/, desktop-agent/, and
browser-extension/) to apply every fix from this conversation.

    python apply_nova_fixes.py

What it does:
  1. Writes 18 fixed files to their correct paths (backs up anything it
     overwrites to apply_nova_fixes_backup/ first, so nothing is lost).
  2. Deletes the one dead duplicate folder and any accidentally-committed
     voice recordings that can't be fixed by just writing a file.
  3. Prints the exact commands left to run -- these genuinely need your
     terminal (starting Docker, installing packages, migrating the
     database, starting servers) and can't be done by this script alone
     since it doesn't know what's already running.

Safe to run more than once.
"""
