TO_DELETE = [
    "dashboard/app/dashboard/admin",  # dead duplicate of the real dashboard/app/admin
]


def write_files():
    written, skipped_same = 0, 0
    for rel_path, b64_content in FILES_B64.items():
        target = PROJECT_ROOT / rel_path
        new_bytes = base64.b64decode(b64_content)

        if target.exists():
            if target.read_bytes() == new_bytes:
                skipped_same += 1
                continue
            backup_path = BACKUP_DIR / rel_path
            backup_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, backup_path)

        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(new_bytes)
        written += 1
        print("  wrote  " + rel_path)

    print("")
    print(str(written) + " file(s) written, " + str(skipped_same) + " already up to date.")
    if written:
        print("Backups of anything overwritten: " + str(BACKUP_DIR.relative_to(PROJECT_ROOT)))


def delete_dead_code():
    for rel_path in TO_DELETE:
        target = PROJECT_ROOT / rel_path
        if target.exists():
            shutil.rmtree(target)
            print("  deleted  " + rel_path + "/")
        else:
            print("  (already gone)  " + rel_path + "/")

    voice_samples_dir = PROJECT_ROOT / "backend" / "data" / "voice_samples"
    if voice_samples_dir.exists():
        removed = 0
        for item in voice_samples_dir.rglob("*"):
            if item.is_file() and item.name != ".gitkeep":
                item.unlink()
                removed += 1
        if removed:
            print("  deleted  " + str(removed) + " committed voice sample file(s) under backend/data/voice_samples/")
        else:
            print("  (no committed voice sample files found -- good)")


NEXT_STEPS = """
[Terminal 1 -- BACKEND -- start this first, always]
  cd backend
  docker compose up -d
  python -m venv .venv                     (skip if you already have one)
  .venv\\Scripts\\activate
  pip install -r requirements.txt          (skip if already installed)
  alembic upgrade head
  uvicorn app.main:app --host 127.0.0.1 --port 8000

  Then check http://127.0.0.1:8000/health in a browser. Don't move on
  until that loads.

[Terminal 2 -- DASHBOARD -- the website]
  cd dashboard
  npm install                              (skip if already installed)
  npm run dev
  Opens at http://localhost:3000

[Terminal 3 -- DESKTOP AGENT -- the actual assistant]
  cd desktop-agent
  python -m venv venv                      (skip if you already have one)
  venv\\Scripts\\activate
  pip install -r requirements.txt          (skip if already installed)
  python main.py

[BROWSER EXTENSION -- optional, no terminal needed]
  Chrome -> chrome://extensions -> enable Developer mode ->
  Load unpacked -> select the browser-extension folder
"""


def main():
    if not (PROJECT_ROOT / "backend").is_dir() or not (PROJECT_ROOT / "desktop-agent").is_dir():
        print("ERROR: this doesn't look like the project root.")
        print("This script is in: " + str(PROJECT_ROOT))
        print("Move it into the folder that directly contains backend/, dashboard/,")
        print("desktop-agent/, and browser-extension/, then run it again.")
        sys.exit(1)

    print("Writing fixed files...")
    write_files()
    print("")
    print("Deleting dead/leftover files...")
    delete_dead_code()

    print("")
    print("=" * 70)
    print("Done. Now run these, in order, in SEPARATE terminal windows:")
    print("=" * 70)
    print(NEXT_STEPS)


if __name__ == "__main__":
    main()
